#!/usr/bin/env python3
"""Spike 2 mini-emitter: .hy -> .go with //line mapping.

NOT a compiler: fixed-template emission to test Go's toolchain behavior with
//line directives (error positions + stack traces pointing back to .hy source).
The real Phase-1 emitter replaces this file; the CONTRACT it tests is what
matters: emitted code must build with `go build` and map diagnostics home.
"""
import sys

TEMPLATE = '''\
// Code generated by the Hybrid spike-2 mini emitter. DO NOT EDIT.
//
//line {hy_path}:1:1
package {pkg}

import (
\t"fmt"
\t"os"
)

//line {hy_path}:9:1
func Greet(name string) string {{
//line {hy_path}:10:5
\treturn "hello, " + name + " (from Hybrid)"
}}

//line {hy_path}:14:1
func Boom() {{
//line {hy_path}:15:5
\tpanic("boom from Hybrid source")
}}

//line {hy_path}:19:1
func Main() {{
//line {hy_path}:20:5
\tif len(os.Args) > 1 && os.Args[1] == "boom" {{
//line {hy_path}:21:9
\t\tBoom()
\t}}
//line {hy_path}:23:5
\tfmt.Println(Greet("world"))
}}
'''


def emit(hy_path, go_path, pkg):
    with open(go_path, "w") as f:
        f.write(TEMPLATE.format(hy_path=hy_path, pkg=pkg))
    print("emitted {} (mapped back to {})".format(go_path, hy_path))


if __name__ == "__main__":
    emit(sys.argv[1], sys.argv[2], sys.argv[3] if len(sys.argv) > 3 else "main")
